return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'uk','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-09-09T22:42:23+00:00','po-revision-date'=>'2026-09-09T22:42:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Settings'=>'Налаштування','That does not look like a Zinn® Chat key. Copy it from the Live chat page of your Zinn Digital® dashboard — it starts with zc_.'=>'Це не схоже на ключ Zinn® Chat. Скопіюйте його зі сторінки Живого чату панелі керування Zinn Digital® — він починається з zc_.','Add your chat key before switching the chat on — without it there is nothing for the widget to connect to.'=>'Додайте свій ключ чату перед тим, як увімкнути чат — без нього віджету ні до чого підключатися.','The chat is live on this site.'=>'Чат працює на цьому сайті.','The chat is switched off. Nothing is loaded on your site.'=>'Чат вимкнено. На вашому сайті нічого не завантажено.','Chat key'=>'Ключ чату','Copy this from the Live chat page of your %s.'=>'Скопіюйте це зі сторінки живого чату вашого %s.','Zinn Digital® dashboard'=>'Панель керування Zinn Digital®','Show the chat'=>'Показати чат','Until you tick this, the plugin adds nothing at all to your pages — no script, no cookie, no requests.'=>'Доки ви не встатите цей прапорець, плагін взагалі нічого не додає до ваших сторінок — жодного скрипта, жодного файлу cookie, жодних запитів.','%s — guides and services'=>'%s — посібники та послуги','User guides'=>'Посібники користувача','Read the %s user guide'=>'Прочитайте посібник користувача %s','Hide this'=>'Приховати це','Zinn® hosting for WordPress'=>'Хостинг Zinn® для WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, щоденні резервні копії, безкоштовна міграція та панель керування, створена для тих, хто керує кількома сайтами.','The Zinn® marketplace'=>'Маркетплейс Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Купуйте та продавайте готові сайти, домени та розміщення посилань із безпечним утриманням коштів, доки обидві сторони не будуть задоволені.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — наймайте професіоналів, які роблять це своєю роботою','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Наш глобальний ринок фрилансу: переглядайте понад 10 000 готових послуг від письменників, дизайнерів, розробників та спеціалістів з SEO або опублікуйте проєкт і дозвольте їм робити ставки.','See the Zinn Digital® release notes.'=>'Перегляньте нотатки до випуску Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Завантажене оновлення не пройшло перевірку цілісності та не було встановлене.']];